package com.cryptostrategy.platform.leaderboard.internal;import com.cryptostrategy.platform.evaluation.api.model.RankingVersion;import com.cryptostrategy.platform.experiment.api.ExperimentId;import com.cryptostrategy.platform.leaderboard.api.model.LeaderboardEntry;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;final class LeaderboardFingerprintV1{String calculate(ExperimentId experiment,RankingVersion ranking,List<LeaderboardEntry> entries){StringBuilder value=new StringBuilder("leaderboard-v1\n").append(experiment.value()).append('\n').append(ranking.value()).append('\n');entries.forEach(e->value.append(e.rank()).append('|').append(e.evaluationFingerprint()).append('|').append(e.score()).append('|').append(e.maximumDrawdown()).append('\n'));try{return "sha256:"+HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.toString().getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
